package com.aoo.bcg.common.id;import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DistributedIdGeneratorTest{@Test void nodesAndConcurrentBatchesNeverCollide()throws Exception{Clock clock=Clock.fixed(Instant.parse("2026-08-23T00:00:00Z"),ZoneOffset.UTC);List<DistributedIdGenerator>nodes=java.util.stream.LongStream.range(0,32).mapToObj(id->new DistributedIdGenerator(id,clock)).toList();Set<Long>ids=ConcurrentHashMap.newKeySet();try(var pool=Executors.newFixedThreadPool(32)){List<Future<?>>tasks=new ArrayList<>();for(var node:nodes)tasks.add(pool.submit(()->{for(int i=0;i<4000;i++)assertTrue(ids.add(node.getAsLong()));}));for(var task:tasks)task.get();}assertEquals(128000,ids.size());}@Test void clockRollbackFailsClosed(){class MutableClock extends Clock{long value=Instant.parse("2026-01-01T00:00:00Z").toEpochMilli();public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return Instant.ofEpochMilli(value);}}var clock=new MutableClock();var ids=new DistributedIdGenerator(1,clock);ids.getAsLong();clock.value--;assertThrows(IllegalStateException.class,ids::getAsLong);}@Test void exhaustedMillisecondFailsWithinBudgetInsteadOfBusyWaiting(){var ids=new DistributedIdGenerator(1,Clock.fixed(Instant.parse("2026-08-23T00:00:00Z"),ZoneOffset.UTC));for(int i=0;i<4096;i++)ids.getAsLong();assertTimeoutPreemptively(Duration.ofMillis(100),()->assertThrows(IllegalStateException.class,ids::getAsLong));}}
